package com.hbm.item.designator.advanced;
import net.minecraft.core.component.DataComponents;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.component.CustomData;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Original add/subtract/current-coordinate packet, authenticated against the actual still-held manual designator. */
public record ManualDesignatorControl(InteractionHand hand,int operator,int value,int reference)implements CustomPacketPayload{public static final Type<ManualDesignatorControl> TYPE=new Type<>(ResourceLocation.parse("hbm:manual_designator_control"));public static final StreamCodec<RegistryFriendlyByteBuf,ManualDesignatorControl> CODEC=StreamCodec.of((b,p)->{b.writeEnum(p.hand);b.writeInt(p.operator);b.writeInt(p.value);b.writeInt(p.reference);},b->new ManualDesignatorControl(b.readEnum(InteractionHand.class),b.readInt(),b.readInt(),b.readInt()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent event){event.registrar("1").playToServer(TYPE,CODEC,(p,c)->c.enqueueWork(()->{if(p.operator<0||p.operator>2||p.reference<0||p.reference>1||p.operator!=2&&p.value!=1&&p.value!=5&&p.value!=10&&p.value!=50&&p.value!=100)return;var player=c.player();var stack=player.getItemInHand(p.hand);if(!(stack.getItem() instanceof ManualDesignatorItem))return;CustomData.update(DataComponents.CUSTOM_DATA,stack,tag->{String key=p.reference==0?"xCoord":"zCoord";if(p.operator==2)tag.putInt(key,(int)Math.round(p.reference==0?player.getX():player.getZ()));else tag.putInt(key,tag.getInt(key)+(p.operator==0?p.value:-p.value));});}));}}
